describe('Mobile Landscape Orientation - Responsive Design', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x', 'landscape');
  });

  it('should display all main content elements correctly in landscape orientation', () => {
    cy.get('header').should('be.visible');
    cy.get('main').should('be.visible');
    cy.get('footer').should('be.visible');

    cy.get('header').should('have.css', 'display').and('not.equal', 'none');
    cy.get('main').should('have.css', 'display').and('not.equal', 'none');
    cy.get('footer').should('have.css', 'display').and('not.equal', 'none');
  });

  it('should not have horizontal scrollbar in landscape orientation', () => {
    cy.window().then((win) => {
      expect(win.innerWidth).to.be.greaterThan(0);
      expect(win.innerHeight).to.be.greaterThan(0);
    });

    cy.get('body').then(($body) => {
      const bodyWidth = $body[0].scrollWidth;
      const windowWidth = $body[0].clientWidth;
      expect(bodyWidth).to.equal(windowWidth);
    });
  });

  it('should maintain proper spacing and padding in landscape mode', () => {
    cy.get('main').should('have.css', 'padding').and('not.equal', '0px');
    cy.get('header').should('have.css', 'padding').and('not.equal', '0px');

    cy.get('main').invoke('outerHeight').should('be.greaterThan', 0);
  });

  it('should handle navigation menu correctly in landscape orientation', () => {
    cy.get('nav').should('be.visible');
    cy.get('nav a, nav button').should('have.length.greaterThan', 0);

    cy.get('nav a, nav button').each(($el) => {
      cy.wrap($el).should('be.visible');
    });
  });

  it('should display images and media without distortion in landscape', () => {
    cy.get('img').each(($img) => {
      cy.wrap($img).should('be.visible');
      cy.wrap($img).should('have.css', 'max-width').and('not.equal', 'none');
    });
  });

  it('should handle text content without overflow in landscape orientation', () => {
    cy.get('p, h1, h2, h3, span').each(($el) => {
      cy.wrap($el).should('have.css', 'overflow').and('not.equal', 'visible');
    });
  });

  it('should maintain touch-friendly button sizes in landscape mode', () => {
    cy.get('button, a[role="button"]').each(($btn) => {
      cy.wrap($btn).invoke('outerHeight').should('be.gte', 44);
      cy.wrap($btn).invoke('outerWidth').should('be.gte', 44);
    });
  });
});
